def effect_reverse(samples, rate, channels, args):
    if len(args) != 0:
        return None, None, None, get_effect_usage_error('reverse'), None
    nframes = len(samples)//channels if channels>0 else 0
    new_samples = []
    for n in range(nframes-1, -1, -1):
        for c in range(channels):
            new_samples.append(samples[n*channels + c])
    return new_samples, rate, channels, None, (0,0)

